/**
 * 高性能缓存模块
 * 支持内存缓存、TTL 过期、LRU 淘汰策略、缓存预热
 */

class CacheNode {
  constructor(key, value, ttl) {
    this.key = key;
    this.value = value;
    this.createdAt = Date.now();
    this.expiresAt = ttl ? this.createdAt + ttl : null;
    this.prev = null;
    this.next = null;
  }

  isExpired() {
    if (!this.expiresAt) return false;
    return Date.now() > this.expiresAt;
  }
}

class LRUCache {
  /**
   * 创建 LRU 缓存实例
   * @param {Object} options - 配置选项
   * @param {number} options.maxSize - 最大缓存项数
   * @param {number} options.defaultTTL - 默认 TTL（毫秒）
   * @param {Function} options.onEvict - 淘汰回调函数
   */
  constructor(options = {}) {
    this.maxSize = options.maxSize || 1000;
    this.defaultTTL = options.defaultTTL || null;
    this.onEvict = options.onEvict || null;
    
    // 核心数据结构
    this.cache = new Map(); // key -> CacheNode
    this.head = new CacheNode(null, null); // 虚拟头节点
    this.tail = new CacheNode(null, null); // 虚拟尾节点
    this.head.next = this.tail;
    this.tail.prev = this.head;
    
    // 统计信息
    this.stats = {
      hits: 0,
      misses: 0,
      evictions: 0,
      expirations: 0
    };
  }

  /**
   * 将节点移动到链表头部（最近使用）
   */
  _moveToFront(node) {
    // 先从原位置移除
    node.prev.next = node.next;
    node.next.prev = node.prev;
    
    // 插入到头部
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next.prev = node;
    this.head.next = node;
  }

  /**
   * 从链表中移除节点
   */
  _removeNode(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  /**
   * 淘汰最久未使用的节点
   */
  _evict() {
    if (this.cache.size >= this.maxSize) {
      const lruNode = this.tail.prev;
      if (lruNode !== this.head) {
        this._removeNode(lruNode);
        this.cache.delete(lruNode.key);
        this.stats.evictions++;
        
        if (this.onEvict) {
          this.onEvict(lruNode.key, lruNode.value);
        }
      }
    }
  }

  /**
   * 获取缓存值
   * @param {string} key - 缓存键
   * @returns {*} 缓存值，未找到返回 undefined
   */
  get(key) {
    const node = this.cache.get(key);
    
    if (!node) {
      this.stats.misses++;
      return undefined;
    }
    
    // 检查是否过期
    if (node.isExpired()) {
      this._removeNode(node);
      this.cache.delete(key);
      this.stats.expirations++;
      this.stats.misses++;
      return undefined;
    }
    
    // 移动到头部（标记为最近使用）
    this._moveToFront(node);
    this.stats.hits++;
    
    return node.value;
  }

  /**
   * 设置缓存值
   * @param {string} key - 缓存键
   * @param {*} value - 缓存值
   * @param {number} ttl - TTL（毫秒），不传则使用默认值
   */
  set(key, value, ttl = this.defaultTTL) {
    const existingNode = this.cache.get(key);
    
    if (existingNode) {
      // 更新已有项
      existingNode.value = value;
      existingNode.createdAt = Date.now();
      existingNode.expiresAt = ttl ? existingNode.createdAt + ttl : null;
      this._moveToFront(existingNode);
    } else {
      // 创建新项
      this._evict(); // 先检查是否需要淘汰
      
      const node = new CacheNode(key, value, ttl);
      this.cache.set(key, node);
      
      // 插入到头部
      node.next = this.head.next;
      node.prev = this.head;
      this.head.next.prev = node;
      this.head.next = node;
    }
  }

  /**
   * 删除指定键
   * @param {string} key - 缓存键
   * @returns {boolean} 是否成功删除
   */
  delete(key) {
    const node = this.cache.get(key);
    
    if (!node) return false;
    
    this._removeNode(node);
    this.cache.delete(key);
    return true;
  }

  /**
   * 清空所有缓存
   */
  clear() {
    this.cache.clear();
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  /**
   * 检查键是否存在
   * @param {string} key - 缓存键
   * @returns {boolean}
   */
  has(key) {
    const node = this.cache.get(key);
    if (!node) return false;
    if (node.isExpired()) {
      this._removeNode(node);
      this.cache.delete(key);
      return false;
    }
    return true;
  }

  /**
   * 获取缓存大小
   * @returns {number}
   */
  size() {
    return this.cache.size;
  }

  /**
   * 获取统计信息
   * @returns {Object}
   */
  getStats() {
    const total = this.stats.hits + this.stats.misses;
    return {
      ...this.stats,
      hitRate: total > 0 ? (this.stats.hits / total).toFixed(4) : '0',
      size: this.cache.size,
      maxSize: this.maxSize
    };
  }

  /**
   * 重置统计信息
   */
  resetStats() {
    this.stats = {
      hits: 0,
      misses: 0,
      evictions: 0,
      expirations: 0
    };
  }

  /**
   * 预热缓存
   * @param {Array<{key: string, value: *, ttl?: number}>} items - 预热数据
   */
  warmUp(items) {
    for (const item of items) {
      this.set(item.key, item.value, item.ttl);
    }
  }

  /**
   * 获取所有键
   * @returns {string[]}
   */
  keys() {
    const result = [];
    for (const [key, node] of this.cache) {
      if (!node.isExpired()) {
        result.push(key);
      }
    }
    return result;
  }

  /**
   * 过期清理（主动清理所有过期项）
   * @returns {number} 清理的数量
   */
  cleanup() {
    let count = 0;
    const expiredKeys = [];
    
    for (const [key, node] of this.cache) {
      if (node.isExpired()) {
        expiredKeys.push(key);
      }
    }
    
    for (const key of expiredKeys) {
      this.delete(key);
      count++;
    }
    
    this.stats.expirations += count;
    return count;
  }
}

// 导出
module.exports = { LRUCache, Cache: LRUCache, CacheNode };
